def gcd(a: int, b: int) -> int:
    """Greatest common divisor of two non-negative integers, not both zero."""

    # Base case: if either number is zero, return the other (non-zero)
    if a == 0 or b == 0:
        return max(a, b)

    # Recursive case: apply Euclidean algorithm
    return gcd(b, a % b)

# Test function to verify correctness
def check_gcd():
    assert gcd(12, 18) == 6
    assert gcd(7, 13) == 1
    assert gcd(0, 5) == 5
    assert gcd(100, 75) == 25

check_gcd()

