def flatten(xs: list) -> list:
    """Flatten arbitrarily nested lists into a single list, preserving order."""

    def _flatten(x):
        if isinstance(x, list):
            return x + [_flatten(y) for y in x]
        else:
            return x

    return _flatten(xs)
