def is_prime(n: int) -> bool:
    """True if n is a prime number."""

    # Handle edge cases for 0, 1, and negative numbers
    if n <= 1:
        return False

    # Check divisibility from 2 up to the square root of n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

