def is_prime(n: int) -> bool:
    """True if n is a prime number."""

    # Handle edge cases
    if n <= 1:
        return False
    elif n == 2:
        return True

    # Check for factors from 2 to sqrt(n)
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True
