def word_count(s: str) -> dict[str, int]:
    """Count lowercase words split on whitespace."""

    # Splitting the string into words based on whitespace
    words = s.split()

    # Creating a dictionary to store word counts
    word_counts = {}

    for word in words:
        if word.lower() in word_counts:
            word_counts[word.lower()] += 1
        else:
            word_counts[word.lower()] = 1

    return word_counts

