def celsius_to_f(c: float) -> float:
    """Convert Celsius to Fahrenheit, rounded to one decimal place."""

    # Convert Celsius to Fahrenheit using the formula (C * 9/5) + 32
    fahrenheit = (c * 9 / 5) + 32

    return round(fahrenheit, 1)
